// jwt.rs - JWT Authentication Module
use jsonwebtoken::{encode, decode, Header, Algorithm, Validation, EncodingKey, DecodingKey};
use serde::{Serialize, Deserialize};
use chrono::{Utc, Duration};
use uuid::Uuid;
use std::collections::HashMap;

#[derive(Debug, Serialize, Deserialize)]
pub struct Claims {
    pub sub: String,
    pub iat: i64,
    pub exp: i64,
    pub jti: String,
    pub roles: Vec<String>,
    pub permissions: HashMap<String, Vec<String>>,
}

#[derive(Clone)]
pub struct JwtService {
    encoding_key: EncodingKey,
    decoding_key: DecodingKey,
    access_token_ttl: Duration,
    refresh_token_ttl: Duration,
}

impl JwtService {
    pub fn new_rs256(private_key_pem: &[u8], public_key_pem: &[u8]) -> Result<Self, jsonwebtoken::errors::Error> {
        Ok(Self {
            encoding_key: EncodingKey::from_rsa_pem(private_key_pem)?,
            decoding_key: DecodingKey::from_rsa_pem(public_key_pem)?,
            access_token_ttl: Duration::minutes(15),
            refresh_token_ttl: Duration::days(7),
        })
    }

    pub fn new_hs256(secret: &[u8]) -> Self {
        Self {
            encoding_key: EncodingKey::from_secret(secret),
            decoding_key: DecodingKey::from_secret(secret),
            access_token_ttl: Duration::minutes(15),
            refresh_token_ttl: Duration::days(7),
        }
    }

    pub fn create_access_token(&self, user_id: &str, roles: Vec<String>) -> Result<String, jsonwebtoken::errors::Error> {
        let now = Utc::now();
        let claims = Claims {
            sub: user_id.to_string(),
            iat: now.timestamp(),
            exp: (now + self.access_token_ttl).timestamp(),
            jti: Uuid::new_v4().to_string(),
            roles,
            permissions: HashMap::new(),
        };
        encode(&Header::new(Algorithm::RS256), &claims, &self.encoding_key)
    }

    pub fn create_refresh_token(&self, user_id: &str) -> Result<String, jsonwebtoken::errors::Error> {
        let now = Utc::now();
        let claims = Claims {
            sub: user_id.to_string(),
            iat: now.timestamp(),
            exp: (now + self.refresh_token_ttl).timestamp(),
            jti: Uuid::new_v4().to_string(),
            roles: vec![],
            permissions: HashMap::new(),
        };
        encode(&Header::new(Algorithm::RS256), &claims, &self.encoding_key)
    }

    pub fn validate_token(&self, token: &str) -> Result<Claims, jsonwebtoken::errors::Error> {
        let mut validation = Validation::new(Algorithm::RS256);
        validation.validate_exp = true;
        validation.validate_nbf = true;
        validation.required_spec_claims = vec!["exp", "iat", "sub", "jti"];

        decode(token, &self.decoding_key, &validation).map(|data| data.claims)
    }

    pub fn refresh_access_token(&self, refresh_token: &str) -> Result<(String, String), jsonwebtoken::errors::Error> {
        let claims = self.validate_token(refresh_token)?;
        let new_access = self.create_access_token(&claims.sub, claims.roles)?;
        let new_refresh = self.create_refresh_token(&claims.sub)?;
        Ok((new_access, new_refresh))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const TEST_SECRET: &[u8] = b"test-secret-key-for-testing-only";

    #[test]
    fn test_hs256_token_roundtrip() {
        let service = JwtService::new_hs256(TEST_SECRET);
        let token = service.create_access_token("user123", vec!["admin".to_string()]).unwrap();
        let claims = service.validate_token(&token).unwrap();
        assert_eq!(claims.sub, "user123");
        assert!(claims.roles.contains(&"admin".to_string()));
    }
}
